import json

def publish(draft):
    if not isinstance(draft.get('title'), str) or not isinstance(draft.get('items'), list):
        raise ValueError('Public fields require a title and an items list')
    if any(not isinstance(item, dict) or not isinstance(item.get('title'), str) for item in draft['items']):
        raise ValueError('Each public item requires a text title')
    return {'title': draft['title'], 'items': [{'title': item['title']} for item in draft['items']]}

def backup(data):
    return json.dumps(data)

def restore(blob):
    return json.loads(blob)
